window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"7bEk8deBxBg","speaker":"Godwin Friday","role":"Prime Minister","country":"Saint Vincent and Grenadines","region":"Latin America & Caribbean","url":"https://www.youtube.com/watch?v=7bEk8deBxBg","date":"20260925","title":"🇻🇨 Saint Vincent and Grenadines - Prime Minister Addresses UN General Assembly 81st Session | #UNGA","seconds":1298,"words":2308,"counts":{"claims":32,"promises":4,"attacks":0},"topics":[{"topic":"Climate finance","share":0.1219,"seconds":158},{"topic":"UN reform","share":0.1063,"seconds":138},{"topic":"Climate change","share":0.1013,"seconds":132},{"topic":"UN credibility","share":0.094,"seconds":122},{"topic":"Haiti","share":0.0651,"seconds":84},{"topic":"Venezuela","share":0.0592,"seconds":77},{"topic":"Historical justice","share":0.0538,"seconds":70},{"topic":"UN leadership","share":0.0523,"seconds":68},{"topic":"Middle East","share":0.052,"seconds":67},{"topic":"Caribbean security","share":0.0508,"seconds":66},{"topic":"Multilateralism","share":0.0497,"seconds":64},{"topic":"UNGA protocol","share":0.0494,"seconds":64},{"topic":"Saint Vincent and Grenadines governance","share":0.0488,"seconds":63},{"topic":"UNGA","share":0.0486,"seconds":63},{"topic":"Taiwan","share":0.0467,"seconds":61}],"timeline":[[2,66,"UNGA protocol"],[69,129,"UN credibility"],[133,196,"Saint Vincent and Grenadines governance"],[196,261,"Climate change"],[263,326,"UNGA"],[328,392,"Multilateralism"],[394,484,"UN reform"],[486,554,"UN leadership"],[563,630,"Climate change"],[632,700,"Climate finance"],[701,792,"Climate finance"],[792,859,"Middle East"],[862,947,"Haiti"],[948,1014,"Caribbean security"],[1016,1093,"Venezuela"],[1094,1154,"Taiwan"],[1157,1226,"Historical justice"],[1228,1290,"UN credibility"],[1291,1339,"UN reform"]],"stances":{"UNGA protocol":"Godwin Friday extends greetings to the President and offers support for the upcoming session.","UN credibility":"Godwin Friday expresses gratitude for the Secretary-General's leadership and states that trust in the multilateral system has declined while cynicism has grown.","Saint Vincent and Grenadines governance":"Godwin Friday states that his government is committed to transparent governance, integrity in individual actions, and using public resources to improve the lives of ordinary people.","Climate change":"Godwin Friday states that Saint Vincent and the Grenadines faces vulnerability from climate change but will not let it limit their ambitions.","UNGA":"Godwin Friday expresses that he was moved by the hope and passion of previous speakers and remains determined to maintain a hopeful spirit while acknowledging the UN's flaws but rejecting abandonment.","Multilateralism":"Godwin Friday argues that humanity needs the United Nations as an inclusive space and warns that retreating from multilateralism harms small states and everyone.","UN reform":"Godwin Friday argues that the United Nations must undergo organizational reform, particularly regarding the Security Council and inclusiveness, to restore trust and effectively address modern challenges.","UN leadership":"Godwin Friday endorses Caroline Rodriguez Burket and argues that the time has come for a woman to serve as Secretary General.","Climate finance":"Godwin Friday argues that small states cannot sustainably borrow to replace climate disaster losses and calls for financial reforms based on vulnerability rather than income.","Middle East":"Godwin Friday calls for a permanent ceasefire in the Middle East, protection of civilians, and a two-state solution.","Haiti":"Godwin Friday expresses that the insecurity in Haiti is a shared pain for the region and supports CARICOM's efforts to fund security and elections.","Caribbean security":"Godwin Friday calls for decisive action to stop the smuggling of weapons into the Caribbean and highlights that these weapons are manufactured in industrial nations, not locally.","Venezuela":"Godwin Friday states that St. Vincent and the Grenadines provided emergency assistance to Venezuela following a devastating earthquake.","Taiwan":"Godwin Friday calls for Taiwan's meaningful participation in the United Nations system and its specialized agencies.","Historical justice":"Godwin Friday expresses encouragement regarding the UN resolution on trafficking and calls for further action following recent conferences."},"claims":[{"t":118,"quote":"trust in the multilateral system is Hope has retreated while cynicism and doubt have grown","topic":"UN credibility","kind":"fact"},{"t":148,"quote":"I come here for the first time representing my country, St. Vincent and the Grenadines with a clear mandate","topic":"Saint Vincent and Grenadines governance","kind":"fact"},{"t":173,"quote":"We are a small democratic multi island Caribbean nation committed to multilateralism and the peaceful resolution of disputes","topic":"Saint Vincent and Grenadines governance","kind":"fact"},{"t":204,"quote":"Having experienced only two years ago the sudden destructive power of a category 5","topic":"Climate change","kind":"fact"},{"t":263,"quote":"I come at this point in the debate having had the privilege of listening to other leaders who spoke before me.","topic":"UNGA","kind":"fact"},{"t":319,"quote":"We all know that the United Nations has its flaws, but we must not seek to abandon it.","topic":"UNGA","kind":"fact"},{"t":354,"quote":"We believe profoundly that more than ever humanity needs the United Nations.","topic":"Multilateralism","kind":"fact"},{"t":374,"quote":"As a global institution, the United Nations is fundamentally an inclusive space where every nation can play a role in addressing our common A retreat from multilateralism undermines the interests of small states and indeed of everyone.","topic":"Multilateralism","kind":"fact"},{"t":437,"quote":"The United Nations governance model designed in 1945 cannot adequately address the security and economic challenges of today.","topic":"UN reform","kind":"fact"},{"t":486,"quote":"St. Vincent and the Grenadines is pleased to join other Caribbean community members in endorsing the candidacy of her excellency Caroline Rodriguez Burket of Trinidad of Guyana and of the region of Latin America and the Caribbean.","topic":"UN leadership","kind":"fact"},{"t":526,"quote":"I walked the halls of this historic building and admired the on the walls the impressive portraits of the nine men who have served as Secretary General since 1946.","topic":"UN leadership","kind":"number"},{"t":609,"quote":"In July 2024, Hurricane Barrel struck in Vincent and the Grenardines","topic":"Climate change","kind":"fact"},{"t":632,"quote":"Small states cannot continue borrowing merely to replace what climate related disasters repeatedly destroy.","topic":"Climate finance","kind":"fact"},{"t":642,"quote":"We cannot continue to walk up the down escalator pretending it is development.","topic":"Climate finance","kind":"fact"},{"t":720,"quote":"affordable, patient, concessional capital is not charity to small states. It is justice for states that contribute the least to the climate crisis yet bear the highest costs.","topic":"Climate finance","kind":"fact"},{"t":761,"quote":"International conflicts far from our shores in Ukraine and the Middle East continue to have devastating consequences for our daily lives, disrupting agricultural trade and global food stability and driving up fuel prices and shipping","topic":"Climate finance","kind":"fact"},{"t":797,"quote":"we call for a permanent ceasefire in the Middle East, the protection of civilians, and the realization of a two-state solution guaranteeing peace and security for Palestine and Israel.","topic":"Middle East","kind":"fact"},{"t":884,"quote":"Nearly four decades ago, the Trinidadian Calypsonian David Rudder sang a lament to Haiti.","topic":"Haiti","kind":"fact"},{"t":924,"quote":"The insecurity of the Haitian people plagued by gang violence and political uncertainty is a pain felt across our","topic":"Haiti","kind":"fact"},{"t":961,"quote":"We don't make these weapons in the Caribbean. They are manufactured in industrial nations and smuggled across borders into our region into our countries.","topic":"Caribbean security","kind":"fact"},{"t":990,"quote":"For more than three decades, this assembly has said that the economic embargo imposed in Cuba must end.","topic":"Caribbean security","kind":"fact"},{"t":1029,"quote":"When earthquake devastating earthquake struck Venezuela earlier this year, claiming thousands of lives","topic":"Venezuela","kind":"fact"},{"t":1036,"quote":"St. Vincent and the Grenadines stood up in solidarity contributing emergency assistance through a coordinated caraccom relief effort","topic":"Venezuela","kind":"self_credit"},{"t":1094,"quote":"Taiwan has shown time and again that they are prepared to be a responsible member of the international community.","topic":"Taiwan","kind":"fact"},{"t":1131,"quote":"The Caribbean community has for over a decade advanced a 10-point plan for reparatory justice, seeking acknowledgement, repair, and genuine partnership to address the historic injustices of the enslavement of African people and the near annihilation of our indigenous populations.","topic":"Taiwan","kind":"fact"},{"t":1159,"quote":"in March 2026, this assembly strongly adopted a resolution sponsored by Ghana and supported by the African Union and CARACOM declaring the trafficking of enslaved Africans and racialized cattle enslavement of Africans as the gravest crime against humanity.","topic":"Historical justice","kind":"fact"},{"t":1191,"quote":"after the follow-up conference in Accra in June, momentum grows","topic":"Historical justice","kind":"fact"},{"t":1239,"quote":"trust is restored when the smallest and most vulnerable nations feel they are included and that their concerns are addressed.","topic":"UN credibility","kind":"fact"},{"t":1249,"quote":"Trust is restored when a national debt is restructured to be fairer.","topic":"UN credibility","kind":"fact"},{"t":1254,"quote":"It is restored when hurricane response arrives in time and when the benefits of new technology such as artificial intelligence is shared rather than hoarded and priced out of reach.","topic":"UN credibility","kind":"fact"},{"t":1267,"quote":"It is restored when an embargo denounced in this chamber is finally lifted, when peace in a conflict is secured, and when a historical wrong is made right.","topic":"UN credibility","kind":"fact"},{"t":1291,"quote":"The United Nations will live up to its name.","topic":"UN reform","kind":"fact"}],"promises":[{"t":63,"quote":"You can count on our support and cooperation.","topic":"UNGA protocol","kind":"promise"},{"t":240,"quote":"We will be resilient and will work individually and collectively to transcend our vulnerability.","topic":"Climate change","kind":"promise"},{"t":249,"quote":"we come to this August assembly not as mayor petitioners but as partners to play our part in making our world a better place.","topic":"Climate change","kind":"promise"},{"t":782,"quote":"We therefore join others here and call for an immediate end to the war in Ukraine with full respect for state sovereignty","topic":"Climate finance","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":"UNGA protocol","text":"The assembly will hear an address by his excellency Godwin Friday, prime minister and minister for finance, legal affairs and justice, economic planning and private sector development of San Vincent and the Grenadines. I request the protocol to escort his excellency and invite his excellency to address the assembly. Mr. President, greetings from the government and people of St. Vincent and the Grenardines. Mr. President, we congratulate you on your election to preside over this session of the General Assembly. You can count on our support and cooperation."},{"t":69,"topic":"UN credibility","text":"Secretary General Antonio Gutierrez, we are extremely grateful to you for your bold leadership and determined advocacy for human rights, justice, and peace. We thank you for standing up for small and vulnerable nations. The theme restoring trust, managing transformation, a united nations that delivers for all speaks directly to the anxieties of our and also to the hopes of small states like mine. As we have heard from many speakers in this chamber, trust in the multilateral system is Hope has retreated while cynicism and doubt have grown."},{"t":133,"topic":"Saint Vincent and Grenadines governance","text":"we hear the insistent calls for justice, peace, and for a rules-based international order that applies equally to all nations. Mr. President, I come here for the first time representing my country, St. Vincent and the Grenadines with a clear mandate and a commitment that governance must be transparent, that individual actions must reflect integrity and that public resources must be used to improve the lives of ordinary people. We are a small democratic multi island Caribbean nation committed to multilateralism and the peaceful resolution of disputes. Those principles serve us well and we believe should bind all of us in this We in St."},{"t":196,"topic":"Climate change","text":"Vincent and the Grenadines experience firsthand the vulnerability of living on the front lines of climate change. Having experienced only two years ago the sudden destructive power of a category 5 We also feel enormous strains imposed on small nations and our small open economy by distant wars that have disrupted supply chains and by decisions made in places where our voice is never heard. Yet we will not let vulnerability define us or limit our ambitions. We will be resilient and will work individually and collectively to transcend our vulnerability. So, Mr. President, we come to this August assembly not as mayor petitioners but as partners to play our part in making our world a better place."},{"t":263,"topic":"UNGA","text":"I come at this point in the debate having had the privilege of listening to other leaders who spoke before me. And Mr. President, I must tell you I was moved by the hopeful vision, the fiery passion, the boundless generosity and caring of many of the speakers. They lifted my spirit and I am determined that that is where my spirit shall remain. I owe it to the people who sent me here to be hopeful. I owe it also to people whom I have never met, who come from places I have never been to, but who nevertheless are my brothers and And so that brings us to the task at We all know that the United Nations has its flaws, but we must not seek to abandon it."},{"t":328,"topic":"Multilateralism","text":"It is what we have made it. Some, no doubt, are more culpable than others, but in one way or another, we are all involved. We speak of culpability not merely to point a finger of blame but to understand better where the solutions may lie. We believe profoundly that more than ever humanity needs the United Nations. Try to imagine a world without it. Where would we go to have the conversations we having now and that we are having throughout the week? And that is only the beginning. As a global institution, the United Nations is fundamentally an inclusive space where every nation can play a role in addressing our common A retreat from multilateralism undermines the interests of small states and indeed of everyone."},{"t":394,"topic":"UN reform","text":"But we acknowledge that our support for the United Nations must be matched by our willingness to embrace reform to make it more effective. Trust cannot be built or restored by declarations alone. It is only when ordinary people see that cooperation makes their lives safer, richer, and happier. that trust will be Mr. President, let us restore trust through organizational reform and greater inclusiveness. The United Nations governance model designed in 1945 cannot adequately address the security and economic challenges of today. Therefore, we join with other nations in calling for reform, specifically of the security council to include a permanent member from the continent of Africa with all the attendant rights and Failure to do so will only confirm that the current composition is not about governance and fairness, but about Further, as we proceed with selecting our next secretary general, let us be more open and inclusive."},{"t":486,"topic":"UN leadership","text":"St. Vincent and the Grenadines is pleased to join other Caribbean community members in endorsing the candidacy of her excellency Caroline Rodriguez Burket of Trinidad of Guyana and of the region of Latin America and the Caribbean. We know her as a distinguished diplomat, a principled multilateralist, and a compelling advocate for developing countries and small states. Mr. President, as this is my first time here, like a tourist, I walked the halls of this historic building and admired the on the walls the impressive portraits of the nine men who have served as Secretary General since 1946. And while I appreciated the outstanding caliber and service of those men, I nevertheless could not resist thinking that after eight decades, surely the time has come for an equally capable woman to be Secretary General."},{"t":563,"topic":"Climate change","text":"We believe Ambassador Caroline Rodriguez Burkehead of Guyana is well suited to be that Mr. President, for small island developing states, climate change is not a distant forecast. It is a present danger and recurring financial emergency. We suffer the scourge of sargasm seaweed that damages our tourism. We worry about the growing problem of Sahara dust that seriously degrades our air quality across the And of course, we worry constantly about hurricanes. In July 2024, Hurricane Barrel struck in Vincent and the Grenardines and demonstrated once again how a few hours of extreme weather can destroy lives, homes, livelihoods, and infrastructure built over many years and set a country back."},{"t":632,"topic":"Climate finance","text":"Small states cannot continue borrowing merely to replace what climate related disasters repeatedly destroy. We cannot continue to walk up the down escalator pretending it is development. Mr. President, we renew our call for the full operationalization of the multi-dimensional vulnerability index so that access to concessional financing is not constrained by per capita income but reflects the real climate risks small island states face and their limited capacity to respond to such large events. We also call for the swift of reforms set out in the Antigga and Barbuda agenda for SIDS. Further, we support the continuing work of the Bridgetown initiative to reform the international financial including automatic debt service suspension clauses when disaster strikes."},{"t":701,"topic":"Climate finance","text":"Expanded and rechanneled special drawing rights and multilateral development banks that lend like development partners rather than like commercial creditors. Mr. President, we must also accept that affordable, patient, concessional capital is not charity to small states. It is justice for states that contribute the least to the climate crisis yet bear the highest costs. Mr. President, let us restore trust through the pursuit of peace and Trust in the international system begins with the conviction that everyone matters and that the security of small states is as precious as that of great International conflicts far from our shores in Ukraine and the Middle East continue to have devastating consequences for our daily lives, disrupting agricultural trade and global food stability and driving up fuel prices and shipping We therefore join others here and call for an immediate end to the war in Ukraine with full respect for state sovereignty"},{"t":792,"topic":"Middle East","text":"and territorial integrity under the UN charter. And likewise, we call for a permanent ceasefire in the Middle East, the protection of civilians, and the realization of a two-state solution guaranteeing peace and security for Palestine and Israel. Mr. President, St. Vincent and the Grenadines does not stand alone. We stand with our brothers and sisters in the Caribbean community, Caraccom, which is not just a trading block, but a family whose members in these uncertain times need each other more than ever. For us in the Caribbean, peace and security are paramount concerns in our diplomatic efforts. Therefore, as we seek to restore trust, we reaffirm that Latin America and the Caribbean must remain a zone of peace where disputes are settled through peaceful means with adherence to international law and the UN charter."},{"t":862,"topic":"Haiti","text":"We urge that the territorial dispute between Venezuela and Guyana be resolved in this manner within our hemisphere. Other unresolved challenges require immediate principled engagement. Haiti remains our urgent concern. Nearly four decades ago, the Trinidadian Calypsonian David Rudder sang a lament to Haiti. His words are still relevant today. I quote, \"When there is anguish in Porto France, it's still Africa crying. We are outing fires in far away places. When our neighbors are burning, I refuse to believe that we good people will forever turn our hearts and our eyes away. Haiti, I am sorry. And the song goes on. The insecurity of the Haitian people plagued by gang violence and political uncertainty is a pain felt across our We support the efforts of CARICOM and this organization to help fund and provide security to build up critical institutions and create a viable path to general elections."},{"t":948,"topic":"Caribbean security","text":"We must confront the reality of arms trafficking, including assault weapons that are terrorizing Haitian communities and indeed communities across the We don't make these weapons in the Caribbean. They are manufactured in industrial nations and smuggled across borders into our region into our countries. We therefore call upon all countries to take decisive action to stem the illicit flow of weapons and ammunitions across borders and into the Mr. President, Cuba has long been a valued member of our Caribbean family. For more than three decades, this assembly has said that the economic embargo imposed in Cuba must end. Whatever the disagreements exist, the collective punishment of an entire population, denying medicine, denying trade, denying fuel, denying ordinary development cannot be reconciled with the charter we all signed."},{"t":1016,"topic":"Venezuela","text":"My government adds its voice to call re a call renewed year after year in this hall for the embargo to end. When earthquake devastating earthquake struck Venezuela earlier this year, claiming thousands of lives, St. Vincent and the Grenadines stood up in solidarity contributing emergency assistance through a coordinated caraccom relief effort. Mr. President, when tragedy strikes, we must act as our brothers and sisters This too builds and restores trust among nations and strengthens the United Nations. Mr. President friendship also forms is a form of trust and I wish in this August body to recognize our country's 45 years of diplomatic ties and friendship with Taiwan that has seen us work together in development in disaster response, education and in public health."},{"t":1094,"topic":"Taiwan","text":"Taiwan has shown time and again that they are prepared to be a responsible member of the international community. We renew our call for Taiwan's meaningful participation in the United Nations system and its specialized Mr. President, let us also restore trust through support for reparatory justice. The past is not the past when its consequences still shape who is rich and who is poor in the world today. The Caribbean community has for over a decade advanced a 10-point plan for reparatory justice, seeking acknowledgement, repair, and genuine partnership to address the historic injustices of the enslavement of African people and the near annihilation of our indigenous populations."},{"t":1157,"topic":"Historical justice","text":"We are encouraged that in March 2026, this assembly strongly adopted a resolution sponsored by Ghana and supported by the African Union and CARACOM declaring the trafficking of enslaved Africans and racialized cattle enslavement of Africans as the gravest crime against humanity. This is a hopeful and historic event and after the follow-up conference in Accra in June, momentum grows, so necessary actions must follow. When the continent from which our enslaved ancestors were taken and the islands to which they were brought in change in chains spoke in one voice, this chamber listened. The world listened. We expect that more steps will follow from discussions that will be held as part of the Commonwealth heads of government meeting in Antigga and Barbuda in November."},{"t":1228,"topic":"UN credibility","text":"As I conclude, Mr. President, we ask how the United Nations can restore trust while managing In summary, trust is restored when the smallest and most vulnerable nations feel they are included and that their concerns are addressed. Trust is restored when a national debt is restructured to be fairer. It is restored when hurricane response arrives in time and when the benefits of new technology such as artificial intelligence is shared rather than hoarded and priced out of reach. It is restored when an embargo denounced in this chamber is finally lifted, when peace in a conflict is secured, and when a historical wrong is made right. Mr. President, we remain hopeful with necessary changes in the organization and in the mindset of those of us who shape its work."},{"t":1291,"topic":"UN reform","text":"The United Nations will live up to its name. However, we must manage this era of transformation with courage, honesty, and fairness, and including equally the concerns of all the peoples of the world who despite our individual protestations are inevitably part of our shared humanity. Thank you and may God bless us all. On behalf of the assembly, I wish to thank the prime minister and minister of finance, legal affairs and justice, economic planning and private sector development of St. Vincent and the"}],"compare":[{"topic":"UN & its reform","share":0.3506,"mean":0.204,"rank":31,"others":170},{"topic":"Climate Change","share":0.2233,"mean":0.0418,"rank":5,"others":77},{"topic":"Haiti","share":0.0651,"mean":0.0062,"rank":8,"others":11},{"topic":"Venezuela","share":0.0592,"mean":0.0048,"rank":8,"others":11},{"topic":"Reparations","share":0.0538,"mean":0.0041,"rank":9,"others":13},{"topic":"Middle East","share":0.052,"mean":0.0071,"rank":16,"others":19},{"topic":"Latin America","share":0.0508,"mean":0.0044,"rank":10,"others":12},{"topic":"International Law & Order","share":0.0497,"mean":0.0605,"rank":90,"others":102}]};
